window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a8740130688c1863"]={"versions": [{"id": "FIG-a8740130688c1863", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (<code>class HM_AliveSupervision</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform – Platform Health Management (PHM / Health Monitoring), Sub-Feature <em>Alive Supervision</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Konfigurationsstruktur zur frequenzbasierten Lebendigkeitsüberwachung zyklischer Programmabläufe in Adaptive Applications.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AliveSupervision</code> (Klasse / Konfigurationsentität):</strong> Definiert das Überwachungsfenster und die Toleranzkriterien für einen spezifischen Prüfpunkt.</li>\n<li><code>- AliveReferenceCycle</code>: Dauer bzw. Zyklusanzahl des Referenzbeobachtungsintervalls, über das die Checkpoint-Ereignisse akkumuliert und ausgewertet werden.</li>\n<li><code>- ExpectedAliveIndications</code>: Sollwert der erwarteten Checkpoint-Meldungen innerhalb eines <code>AliveReferenceCycle</code>.</li>\n<li><code>- MinMargin</code>: Untere zulässige Toleranzgrenze (negative Abweichung von <code>ExpectedAliveIndications</code>).</li>\n<li><code>- MaxMargin</code>: Obere zulässige Toleranzgrenze (positive Abweichung von <code>ExpectedAliveIndications</code>).</li>\n<li><strong><code>Checkpoint</code> (Klasse / Entität):</strong> Repräsentiert einen eindeutig identifizierbaren, im Code instrumentierten Ausführungspunkt innerhalb einer überwachten Entität (<code>SupervisedEntity</code>).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziation <code>SupervisedCheckpoint</code> von <code>AliveSupervision</code> nach <code>Checkpoint</code> mit Kardinalität <code>1</code>. Eine <code>AliveSupervision</code>-Instanz ist zwingend und exklusiv genau einem <code>Checkpoint</code> zugeordnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger & Zählung:</strong></li>\n<li>Die überwachte Applikation meldet die Ausführung synchron über die funktionale C++ API (z. B. <code>ara::phm::SupervisedEntity::ReportCheckpoint()</code>).</li>\n<li>Der PHM-Dienst inkrementiert den internen Zähler für die referenzierte <code>Checkpoint</code>-Instanz während der Periode <code>AliveReferenceCycle</code>.</li>\n<li><strong>Evaluierungslogik & Statuswechsel:</strong></li>\n<li>Am Ende jedes <code>AliveReferenceCycle</code> prüft der PHM-Algorithmus, ob die Anzahl empfangener Meldungen $N$ innerhalb des Akzeptanzfensters liegt:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le N \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Gutfall:</strong> Alive-Zustand bleibt bzw. wechselt nach <code>ALIVE_OK</code>.</li>\n<li><strong>Fehlerfall:</strong> Bei $N < \\text{Min}$ (Starvation/Deadlock/Crash) oder $N > \\text{Max}$ (Babbling Idiot/Endlosschleife) wechselt der Status nach <code>ALIVE_FAILED</code> bzw. nach konfigurierten Fehlzyklen nach <code>ALIVE_EXPIRED</code>.</li>\n<li><strong>Folgeaktionen:</strong></li>\n<li>Der Alive-Status fließt in die globale State-Machine des PHM ein; bei Verletzung triggert PHM Recovery Actions über das <em>Execution Management</em> / <em>State Management</em> (z. B. Prozess-Neustart, Degradierung in Safe State) oder meldet an das Diagnose-Subsystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (Deployment / ARXML):</strong></li>\n<li><code>AliveReferenceCycle</code> muss exakt auf die Task-Aktivierungsrate des OS (POSIX/Linux/QNX) abgestimmt werden.</li>\n<li><code>MinMargin</code> und <code>MaxMargin</code> müssen Task-Jitter, Scheduling-Latenzen und transiente Lastspitzen abbilden; zu enge Margins führen zu False-Positives im Health-Monitor.</li>\n<li><strong>Implementierungsvertrag (Applikations-Entwickler):</strong></li>\n<li>Checkpoints für <code>AliveSupervision</code> dürfen ausschließlich in streng deterministischen, periodischen Kontrollflüssen aufgerufen werden (z. B. zyklische <code>Execute()</code>-Routinen).</li>\n<li>Der Aufruf von <code>ReportCheckpoint()</code> innerhalb asynchroner Event-Callbacks oder bedingter Verzweigungen ist unzulässig, da dies zu unberechenbaren Indikationszahlen führt.</li>\n</ul>"}, {"id": "FIG-cdda228d867d4127", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (<code>class HM_AliveSupervision</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform – Platform Health Management (PHM / Health Monitoring), Sub-Feature <em>Alive Supervision</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Konfigurationsstruktur zur frequenzbasierten Lebendigkeitsüberwachung zyklischer Programmabläufe in Adaptive Applications.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AliveSupervision</code> (Klasse / Konfigurationsentität):</strong> Definiert das Überwachungsfenster und die Toleranzkriterien für einen spezifischen Prüfpunkt.</li>\n<li><code>- AliveReferenceCycle</code>: Dauer bzw. Zyklusanzahl des Referenzbeobachtungsintervalls, über das die Checkpoint-Ereignisse akkumuliert und ausgewertet werden.</li>\n<li><code>- ExpectedAliveIndications</code>: Sollwert der erwarteten Checkpoint-Meldungen innerhalb eines <code>AliveReferenceCycle</code>.</li>\n<li><code>- FailedReferenceCyclesTolerance</code>: Anzahl tolerierter aufeinanderfolgender Evaluierungszyklen mit verletzter Alive-Bedingung (<code>ALIVE_FAILED</code>), bevor der Zustand endgültig nach <code>ALIVE_EXPIRED</code> wechselt.</li>\n<li><code>- MaxMargin</code>: Obere zulässige Toleranzgrenze (positive Abweichung von <code>ExpectedAliveIndications</code>).</li>\n<li><code>- MinMargin</code>: Untere zulässige Toleranzgrenze (negative Abweichung von <code>ExpectedAliveIndications</code>).</li>\n<li><strong><code>Checkpoint</code> (Klasse / Entität):</strong> Repräsentiert einen eindeutig identifizierbaren, im Code instrumentierten Ausführungspunkt innerhalb einer überwachten Entität (<code>SupervisedEntity</code>).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziation <code>SupervisedCheckpoint</code> von <code>AliveSupervision</code> nach <code>Checkpoint</code> mit Kardinalität <code>1</code>. Eine <code>AliveSupervision</code>-Instanz ist zwingend und exklusiv genau einem <code>Checkpoint</code> zugeordnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger & Zählung:</strong></li>\n<li>Die überwachte Applikation meldet die Ausführung synchron über die funktionale C++ API (z. B. <code>ara::phm::SupervisedEntity::ReportCheckpoint()</code>).</li>\n<li>Der PHM-Dienst inkrementiert den internen Zähler für die referenzierte <code>Checkpoint</code>-Instanz während der Periode <code>AliveReferenceCycle</code>.</li>\n<li><strong>Evaluierungslogik & Statuswechsel:</strong></li>\n<li>Am Ende jedes <code>AliveReferenceCycle</code> prüft der PHM-Algorithmus, ob die Anzahl empfangener Meldungen $N$ innerhalb des Akzeptanzfensters liegt:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le N \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Gutfall:</strong> Alive-Zustand bleibt bzw. wechselt nach <code>ALIVE_OK</code>.</li>\n<li><strong>Fehlerfall:</strong> Bei $N < \\text{Min}$ (Starvation/Deadlock/Crash) oder $N > \\text{Max}$ (Babbling Idiot/Endlosschleife) wechselt der Status nach <code>ALIVE_FAILED</code> bzw. nach konfigurierten Fehlzyklen nach <code>ALIVE_EXPIRED</code>.</li>\n<li><strong>Folgeaktionen:</strong></li>\n<li>Der Alive-Status fließt in die globale State-Machine des PHM ein; bei Verletzung triggert PHM Recovery Actions über das <em>Execution Management</em> / <em>State Management</em> (z. B. Prozess-Neustart, Degradierung in Safe State) oder meldet an das Diagnose-Subsystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (Deployment / ARXML):</strong></li>\n<li><code>AliveReferenceCycle</code> muss exakt auf die Task-Aktivierungsrate des OS (POSIX/Linux/QNX) abgestimmt werden.</li>\n<li><code>MinMargin</code> und <code>MaxMargin</code> müssen Task-Jitter, Scheduling-Latenzen und transiente Lastspitzen abbilden; zu enge Margins führen zu False-Positives im Health-Monitor.</li>\n<li><strong>Implementierungsvertrag (Applikations-Entwickler):</strong></li>\n<li>Checkpoints für <code>AliveSupervision</code> dürfen ausschließlich in streng deterministischen, periodischen Kontrollflüssen aufgerufen werden (z. B. zyklische <code>Execute()</code>-Routinen).</li>\n<li>Der Aufruf von <code>ReportCheckpoint()</code> innerhalb asynchroner Event-Callbacks oder bedingter Verzweigungen ist unzulässig, da dies zu unberechenbaren Indikationszahlen führt.</li>\n</ul>"}], "trans": [{"from": "FIG-a8740130688c1863", "to": "FIG-cdda228d867d4127", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>AliveSupervision</code>: Attribut <code>- FailedReferenceCyclesTolerance</code> neu hinzugefügt.</li>\n</ul>"}]};
